    "complex_roots_note": "Enačba z^n = w ima za w ≠ 0 natanko n rešitev (osnovni izrek algebre, uporabljen na z^n − w; slika tega ne dokazuje); ležijo v ogliščih pravilnega n-kotnika s polmerom |w|^(1/n). Koren z_k ima modul |w|^(1/n) in argument (Arg w + 2πk)/n z glavnim argumentom Arg w iz (−π, π]; koren z₀ je glavni. Oznake korenov skočijo, ko w prečka negativno realno os, množica korenov pa ostane ista. Vsota korenov je 0, produkt pa (−1)^(n+1) w. Vrednosti so izračunane iz koordinat na mreži in zaokrožene.",
