    "patch_split_value_u": "Mesto delitve u₀",
    "patch_split_value_v": "Mesto delitve v₀",
    "patch_split_help": "Krpa se razdeli na prvi del S_L (parametri od 0 do u₀ oziroma v₀) in drugi del S_R (od u₀ oziroma v₀ do 1). Skupaj prekrijeta natanko isto ploskev. Mreža dela S_L je zelena in polna, mreža dela S_R opečnato oranžna in srednje črtkana, krivulja reza pa modra in polna.",
    "patch_pieces_locked": "Med prikazom delov izvirnih kontrolnih točk ni mogoče premikati. Za urejanje izklopi stikalo »Pokaži dele krpe« v zavihku Prikaz.",
    "patch_elevate_heading": "Višanje stopnje",
