    "patch_joins_title": "Stik dveh Bézierjevih krp",
    "prompt_patch_joins_c1": "Premikaj točke krpe A ob skupnem robu in opazuj, kako se prilagajata prvi dve vrstici krpe B. Zakaj teh točk ni mogoče premikati in kaj zagotavlja zveznost C1?",
    "prompt_patch_joins_g1": "Izberi stik G1 in spreminjaj razmerje α. Tangentni ravnini se ujemata, odvoda čez rob pa ne. Kako se to vidi na obeh puščicah in na poročilu o stiku?",
    "coons_patch_title": "Coonsova ploskev",
    "prompt_coons_boundaries": "Premikaj točke robnih krivulj. Kako se ploskev prilagodi robovom in ali jih še vedno natančno doseže?",
    "prompt_coons_blend": "Izmenjaj prikaz med Lc, Ld, B in S. Kako se ploskev S = Lc + Ld − B sestavi iz posameznih delov?",
    "preset_join_c1": "Dve bikubični krpi, stik C1",
    "preset_join_g1": "Dve bikubični krpi, stik G1 (α = 2)",
    "preset_join_c0_kink": "Dve bikubični krpi z ostrim robom (samo C0)",
    "preset_join_teapot": "Čajnik iz Utaha (32 krp, samo ogled)",
    "patch_join_scenes_heading": "Primeri stika",
    "patch_join_capstone_heading": "Čajnik iz Utaha",
    "patch_join_capstone_text": "Čajnik sestavlja 32 bikubičnih Bézierjevih krp, prikaz je samo za ogled in točk ni mogoče premikati. Ker ima vsaka krpa svojo mrežo točk in svoje območje parametrov (u, v), tu ni ene same mreže ali enega parametrskega območja, zato ni točke S(u, v) in ne vstavka. Robne krivulje kažejo šive med krpami: večina sosednjih krp si deli robne kontrolne točke, zato se stikajo brez vrzeli, na ročaju, kljunu in vrhu pokrova pa ostajajo prosti robovi.",
    "patch_join_capstone_source": "Podatki: Utah teapot, Martin Newell, prek knjižnice three.js (TeapotGeometry, licenca MIT, © 2010–2025 avtorji three.js); izvirna koda temelji na programski opremi SPD.",
    "patch_join_capstone_back": "Nazaj na dve krpi",
    "patch_join_heading": "Stik krp A in B",
    "patch_join_mode": "Zveznost stika",
    "patch_join_mode_none": "Brez pogoja (krpi sta neodvisni)",
    "patch_join_mode_c0": "C0 (robova sovpadata)",
    "patch_join_mode_c1": "C1 (odvoda čez rob sta enaka)",
    "patch_join_mode_g1": "G1 (tangentni ravnini sovpadata)",
    "patch_join_mode_help": "Stik je rob u = 1 krpe A in rob u = 0 krpe B. Pri C0 je prva vrstica točk krpe B izpeljana iz A, pri C1 in G1 prvi dve. Izpeljane točke so narisane, ne pa premakljive; vsak premik točke krpe A ali sprememba stopnje jih sproti preračuna.",
    "patch_join_alpha": "Razmerje α",
    "patch_join_alpha_help": "Pri stiku G1 je odvod S_u krpe B ob robu α-kratnik odvoda S_u krpe A (α med 0,25 in 4). Pri α = 1 je stik C1.",
